-- Ids are UUID strings generated by the server.
CREATE TABLE agents (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    instructions TEXT NOT NULL,
    model_id TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE sessions (
    id TEXT PRIMARY KEY,
    agent_id TEXT NOT NULL REFERENCES agents (id),
    title TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL
);

CREATE INDEX sessions_agent_updated_idx ON sessions (agent_id, updated_at DESC);

CREATE TABLE messages (
    id TEXT PRIMARY KEY,
    session_id TEXT NOT NULL REFERENCES sessions (id),
    seq BIGINT GENERATED BY DEFAULT AS IDENTITY,
    role TEXT NOT NULL CHECK (role IN ('user', 'assistant')),
    content TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('complete', 'streaming', 'error', 'canceled')),
    error_code TEXT,
    error_message TEXT,
    adapter TEXT,
    reply_to_id TEXT REFERENCES messages (id),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL
);

CREATE INDEX messages_session_seq_idx ON messages (session_id, seq);
CREATE INDEX messages_streaming_idx ON messages (session_id) WHERE status = 'streaming';

CREATE TABLE approvals (
    id TEXT PRIMARY KEY,
    session_id TEXT NOT NULL REFERENCES sessions (id),
    message_id TEXT NOT NULL REFERENCES messages (id),
    kind TEXT NOT NULL,
    summary TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('pending', 'approved', 'rejected')),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL
);

CREATE INDEX approvals_session_created_idx ON approvals (session_id, created_at);
CREATE UNIQUE INDEX approvals_message_id_idx ON approvals (message_id);

CREATE TABLE tasks (
    id TEXT PRIMARY KEY,
    session_id TEXT NOT NULL REFERENCES sessions (id),
    approval_id TEXT NOT NULL UNIQUE REFERENCES approvals (id),
    status TEXT NOT NULL CHECK (status IN ('running', 'completed')),
    source TEXT NOT NULL,
    result TEXT NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL
);

CREATE INDEX tasks_session_created_idx ON tasks (session_id, created_at);
